import math
from statistics import fmean

def parse_amount(text):
    s = text.strip()
    if not s:
        raise ValueError("empty or whitespace only")
    sign_at_start = False
    result_parts = []
    for c in s:
        if c == '-':
            if len(s) > 0 and (not sign_at_start or c != s[0]) :
                return float('-' + ''.join(c[i] for i in range(1, len(s)) if c[i-1:] not in ['-', '+', '.']))
    try:
        f = float(text)
    except ValueError:
        raise
    if math.isnan(f) or math.isinf(f):
        raise ValueError("non-finite value")
    return f
